const levelIndex=new Map(LEVELS.map((level,index)=>[level.id,index]));

export function getLevelVariants(id){const variants=variantsByLevel.get(Number(id));if(variants)return variants;const base=LEVELS[levelIndex.get(Number(id))];if(!base)throw new RangeError(`Unknown level: ${id}`);return [{...base,variant:0}];}
export function nextLevelId(id){const index=levelIndex.get(id);return index===undefined?null:LEVELS[index+1]?.id??null;}
export function getLevel(id,variant){const level=variant===undefined?LEVELS[levelIndex.get(Number(id))]:getLevelVariants(id).find(x=>x.variant===Number(variant));if(!level)throw new RangeError(`Level ${id} has not been reconstructed`);return level;}
